const tabKia = 845789640;

const kiaDetails = await browserjs(tabKia, () => {
  const text = document.body.innerText;

  // Let's find specific sections
  const findSnippet = (term, len = 200) => {
    const idx = text.toLowerCase().indexOf(term.toLowerCase());
    if (idx === -1) return null;
    return text.substring(Math.max(0, idx - 50), Math.min(text.length, idx + len));
  };

  return {
    url: window.location.href,
    title: document.title,
    priceSnippet: findSnippet("33,790", 250),
    engineSnippet: findSnippet("Turbocharged", 250),
    transSnippet: findSnippet("Dual-Clutch", 250) || findSnippet("transmission", 250),
    warrantySnippet: findSnippet("warranty", 250) || findSnippet("10-year", 250) || findSnippet("100,000", 250),
    steeringSnippet: findSnippet("paddle shifters", 200),
    brakesSnippet: findSnippet("Green", 200) || findSnippet("Brake Calipers", 200)
  };
});

