const tabNHTSA = 845789646;

const recallList = await browserjs(tabNHTSA, () => {
  const recallBlocks = Array.from(document.querySelectorAll(".card, .recall-item, [data-qa='recall-item'], .usa-accordion__content"));
  const text = document.body.innerText;

  // Let's find "NHTSA Campaign Number" or "Recall"
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  const recallLines = [];
  let recording = false;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes("Recalls & Safety Issues") || lines[i].startsWith("Recall date")) {
      recording = true;
    }
    if (recording) {
      recallLines.push(lines[i]);
      if (recallLines.length > 80) break;
    }
  }
  return recallLines;
});

console.log("NHTSA recall lines:", recallList);

