// Query NHTSA API for 2025 Kia K5 recalls
const recallApiRes = await tool.fetch_url({
  url: "https://api.nhtsa.gov/products/vehicle/recalls?modelYear=2025&make=KIA&model=K5&issueType=r"
});

console.log("NHTSA Recall API status:", recallApiRes.status);
if (recallApiRes.body) {
  const data = JSON.parse(recallApiRes.body);
  console.log("Recalls count:", data.count);
  console.log("Recalls results:", JSON.stringify(data.results, null, 2));
}

// Let's also query for 2024 and 2023 Kia K5 recalls to see recent history across the generation
const recall24 = await tool.fetch_url({
  url: "https://api.nhtsa.gov/products/vehicle/recalls?modelYear=2024&make=KIA&model=K5&issueType=r"
});
if (recall24.body) {
  const d24 = JSON.parse(recall24.body);
  console.log("2024 Recalls count:", d24.count, d24.results?.map(r => ({ campaign: r.NHTSACampaignNumber, component: r.Component, summary: r.Summary })));
}

// Query 2025 complaints summary
const compApiRes = await tool.fetch_url({
  url: "https://api.nhtsa.gov/products/vehicle/complaints?modelYear=2025&make=KIA&model=K5&issueType=c"
});
if (compApiRes.body) {
  const cData = JSON.parse(compApiRes.body);
  console.log("Complaints count:", cData.count);
  // Group by component
  const compCount = {};
  cData.results?.forEach(c => {
    compCount[c.components] = (compCount[c.components] || 0) + 1;
  });
  console.log("Complaints by component:", compCount);
}

