// Let's inspect the HTML of the recalls section on NHTSA tab
const pageHTML = await browserjs(tabNHTSA, () => {
  const container = document.querySelector("#recalls, .recalls-section, [id*='recall'], [class*='recall']");
  // Or look for elements containing "Load Recalls"
  const allElements = Array.from(document.querySelectorAll("*"));
  const loadRecallsEl = allElements.find(el => el.children.length === 0 && el.textContent.includes("Load Recalls"));
  return {
    found: !!loadRecallsEl,
    parentHTML: loadRecallsEl ? loadRecallsEl.parentElement.outerHTML : null,
    bodyLength: document.body.innerText.length
  };
});

console.log("NHTSA element check:", pageHTML);

