const tabEdmundsReview = 845789647;

const edmundsContent = await browserjs(tabEdmundsReview, () => {
  const text = document.body.innerText;

  // Find Pros, Cons, and Consumer reviews
  const prosIdx = text.indexOf("Pros");
  const consIdx = text.indexOf("Cons");
  const consumerIdx = text.indexOf("Consumer Reviews") !== -1 ? text.indexOf("Consumer Reviews") : text.indexOf("consumer rating");

  return {
    prosCons: text.substring(prosIdx, consIdx + 500),
    consumerRating: consumerIdx !== -1 ? text.substring(consumerIdx, consumerIdx + 800) : "Not found"
  };
});

console.log("Edmunds pros/cons & consumer info:\n", JSON.stringify(edmundsContent, null, 2));

